import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import type { HTMLAttributes, ReactNode } from "react";
import { CheckCircle, CloseCircle, InfoCircle, Warning } from "reicon-react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "./utils";

const alertStyles = tv({
  base: "group/alert flex gap-3 rounded-xl p-4 shadow-[var(--shadow-card)] ring-1 sm:p-5",
  variants: {
    variant: {
      info: "bg-accent text-accent-foreground ring-primary/15",
      success: "bg-success-subtle text-success-foreground ring-success/15",
      warning: "bg-warning-subtle text-warning-foreground ring-warning/20",
      error: "bg-destructive/10 text-foreground ring-destructive/20",
      neutral: "bg-card text-card-foreground ring-border/70",
    },
  },
  defaultVariants: { variant: "info" },
});

export type AlertVariant = NonNullable<
  VariantProps<typeof alertStyles>["variant"]
>;

export interface AlertProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  title?: string;
  variant?: AlertVariant;
  children?: ReactNode;
}

export function Alert({
  title,
  variant = "info",
  className,
  children,
  ...props
}: AlertProps) {
  return (
    <div
      data-slot="alert"
      data-variant={variant}
      className={alertStyles({ variant, className })}
      {...props}
    >
      {title ? (
        <>
          <AlertIcon />
          <div className="min-w-0">
            <AlertTitle>{title}</AlertTitle>
            <AlertDescription>{children}</AlertDescription>
          </div>
        </>
      ) : (
        children
      )}
    </div>
  );
}

export function AlertIcon({
  className,
  children,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="alert-icon"
      className={cn(
        "mt-0.5 grid size-6 shrink-0 place-items-center",
        className,
      )}
    >
      {children ?? (
        <>
          <InfoCircle
            size={20}
            className="hidden group-data-[variant=info]/alert:block group-data-[variant=neutral]/alert:block group-data-[variant=neutral]/alert:text-muted-foreground"
          />
          <CheckCircle
            size={20}
            className="hidden group-data-[variant=success]/alert:block"
          />
          <Warning
            size={20}
            className="hidden group-data-[variant=warning]/alert:block"
          />
          <CloseCircle
            size={20}
            className="hidden group-data-[variant=error]/alert:block group-data-[variant=error]/alert:text-destructive"
          />
        </>
      )}
    </span>
  );
}

export function AlertTitle({
  className,
  ...props
}: HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h3
      {...props}
      data-slot="alert-title"
      className={cn("text-sm font-semibold tracking-[-0.015em]", className)}
    />
  );
}

export function AlertDescription({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="alert-description"
      className={cn("mt-1 text-sm leading-6", className)}
    />
  );
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost: "text-foreground hover:bg-muted data-[pressed]:bg-muted",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
      nav: "text-foreground hover:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
      nav: "h-9 w-full justify-center px-0 text-xs sm:justify-start sm:px-2.5",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

import type { ComponentProps, ElementType } from "react";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonLinkStyles,
} from "./button-styles";

type ButtonLinkProps = Omit<ComponentProps<"a">, "href"> & {
  href: string;
  as?: ElementType;
  variant?: ButtonVariant;
  size?: ButtonSize;
};

export function ButtonLink({
  children,
  className,
  as: Element = "a",
  variant = "default",
  size = "default",
  ...props
}: ButtonLinkProps) {
  return (
    <Element
      {...props}
      data-slot="button-link"
      data-variant={variant}
      data-size={size}
      className={buttonLinkStyles({ variant, size, className })}
    >
      {children}
    </Element>
  );
}
